import React from "react"
import Layout from "../components/layout"
import { graphql } from "gatsby"

import Seo from "../components/seo"
import About from "../components/construct/About"
import Hire from "../components/construct/Hire"

export const Head = ({ data }) => <Seo title="Sobre nosotros y nuestra propuesta" description={data.allPagesJson.nodes[0].content.description} />

const AboutUsPage = ({ data }) => {
  return (
    <Layout>
      <About data={data} />
      <Hire />
    </Layout>
  )
}

export const query = graphql`
  query {
     allPagesJson(filter: { idPage: { eq: "nosotros" } }) {
      nodes {
        idPage
        content {
          description
          title
        }
      }
    }
  }
`

export default AboutUsPage
